/*
 * Porteiro do webhook: confere o Bearer (que o nó Webhook já validou), a
 * assinatura HMAC do corpo e a idade do timestamp.
 *
 * Por que assinar, se já tem o Bearer: o Bearer prova que quem chamou conhece
 * o token; a assinatura prova que o CORPO não foi alterado no caminho e que
 * esta requisição não é a repetição de uma anterior capturada. Sem a janela de
 * 5 minutos, uma requisição gravada valeria para sempre.
 */
const crypto = require('crypto');

const TOKEN = $env.WEBHOOK_LOGIN_TOKEN; // a MESMA string do site
const TOLERANCIA_SEGUNDOS = 300;

const item = $input.first();
const headers = item.json.headers ?? {};

const recusar = (motivo) => [{ json: { assinatura_ok: false, motivo } }];

if (!TOKEN) return recusar('token_nao_configurado_no_n8n');

/*
 * O corpo CRU, byte a byte. O site assinou estes bytes exatos, então
 * reserializar o JSON (JSON.stringify do objeto já parseado) muda espaços e
 * escapes e quebra o HMAC. Por isso o nó Webhook precisa estar com
 * "Raw Body" ligado.
 */
let bruto;
const bin = item.binary?.data;
if (bin?.data) {
  bruto = Buffer.from(bin.data, 'base64').toString('utf8');
} else if (bin) {
  bruto = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
} else {
  // Raw Body desligado: dá para seguir, mas a assinatura fica frágil.
  bruto = JSON.stringify(item.json.body ?? {});
}

const timestamp = String(headers['x-scnet-timestamp'] ?? '');
const assinatura = String(headers['x-scnet-assinatura'] ?? '');
if (!timestamp || !assinatura) return recusar('headers_de_assinatura_ausentes');

if (!/^\d+$/.test(timestamp)) return recusar('timestamp_invalido');
const idade = Math.abs(Math.floor(Date.now() / 1000) - Number(timestamp));
if (idade > TOLERANCIA_SEGUNDOS) return recusar('timestamp_fora_da_janela');

const esperada = crypto
  .createHmac('sha256', TOKEN)
  .update(timestamp + '.' + bruto)
  .digest('hex');

// Comparação de tempo constante: um `===` vaza, pelo tempo de resposta, quantos
// caracteres iniciais bateram, e isso é o bastante para adivinhar a assinatura.
const a = Buffer.from(esperada, 'utf8');
const b = Buffer.from(assinatura, 'utf8');
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
  return recusar('assinatura_invalida');
}

let payload;
try {
  payload = JSON.parse(bruto);
} catch {
  return recusar('corpo_nao_e_json');
}

return [{ json: { assinatura_ok: true, ...payload } }];

/*
 * Resposta do evento `documento_cliente`.
 *
 * O site exige `id_cliente` aqui: é o único momento em que o n8n diz de quem é
 * o login. Daqui em diante esse id viaja no cookie selado do site, não no
 * formulário, então ninguém troca de cliente no meio do caminho.
 */
const cliente = $input.first()?.json ?? {};

if (!cliente.id_cliente) {
  // Mensagem propositalmente vaga: dizer "documento não cadastrado" confirma,
  // a quem só sabe testar CPFs, quais deles são clientes.
  return [
    {
      json: {
        status: 'erro',
        mensagem: 'Não conseguimos localizar esse documento. Confira e tente de novo.',
      },
    },
  ];
}

const celular = String(cliente.celular ?? '').replace(/\D/g, '');
const email = String(cliente.email ?? '').trim();

// 10 dígitos = fixo com DDD; 11 = celular. Menos que isso não dá para enviar.
const temCelular = celular.length >= 10;
const temEmail = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email);

/*
 * Os contatos vão INTEIROS: o site mascara antes de mandar à tela
 * ("(49)*******234", "ma*****@e****.com"). Mascarar aqui também não faz mal —
 * ele detecta o "*" e não mexe — mas não é necessário.
 *
 * Se nenhum canal for `true`, o site mostra um aviso pedindo que o cliente
 * procure o atendimento, em vez de travar numa tela sem opção.
 */
return [
  {
    json: {
      status: 'ok',
      id_cliente: String(cliente.id_cliente),
      canais: { sms: temCelular, whatsapp: temCelular, email: temEmail },
      contatos: {
        ...(temCelular ? { celular } : {}),
        ...(temEmail ? { email } : {}),
      },
    },
  },
];

/*
 * Evento `envio_codigo`: gera o código de 6 dígitos.
 *
 * O site nunca vê o código — ele só pede o envio e, depois, manda o que o
 * cliente digitou para conferência. Quem gera, envia e guarda é o n8n.
 */
const crypto = require('crypto');

const envelope = $('Validar assinatura').first().json;
const dados = envelope.dados ?? {};

// randomInt é do gerador criptográfico. Math.random() é previsível e não serve
// para nada que autentica alguém.
const codigo = String(crypto.randomInt(0, 1000000)).padStart(6, '0');

/*
 * No banco fica só o hash. Um código de 6 dígitos tem 1 milhão de
 * possibilidades — o SHA-256 aqui não impede quebrá-lo por força bruta offline,
 * mas impede que quem abrir a tabela leia os códigos vivos e entre nas contas
 * antes de eles expirarem, que é o risco real com validade de 5 minutos.
 */
const codigoHash = crypto.createHash('sha256').update(codigo).digest('hex');

return [
  {
    json: {
      id_cliente: String(dados.id_cliente ?? ''),
      documento: String(dados.documento ?? ''),
      metodo: String(dados.metodo ?? ''),
      codigo, // só para o nó de envio; não vai ao banco nem à resposta
      codigo_hash: codigoHash,
    },
  },
];

/*
 * Evento `verificacao_codigo`: transforma o código digitado no mesmo hash que
 * foi gravado no envio, para a query comparar hash com hash.
 *
 * Isso é um nó de código, e não uma expressão no nó Postgres, porque as
 * expressões do n8n rodam num sandbox sem `require` — não há como chamar o
 * módulo crypto de dentro delas.
 */
const crypto = require('crypto');

const dados = $input.first().json.dados ?? {};
const codigo = String(dados.codigo ?? '').replace(/\D/g, '');

return [
  {
    json: {
      id_cliente: String(dados.id_cliente ?? ''),
      documento: String(dados.documento ?? ''),
      codigo_hash: crypto.createHash('sha256').update(codigo).digest('hex'),
    },
  },
];

/*
 * Resposta do evento `verificacao_codigo` — o momento em que o acesso é ou não
 * concedido.
 *
 * Quem decidiu foi a query do nó anterior, em uma única instrução: ela pega o
 * código mais recente ainda válido do cliente, soma uma tentativa e só o marca
 * como usado se o hash bater. Fazer isso em um comando só evita a corrida em
 * que dois envios simultâneos gastam o mesmo código.
 */
const r = $input.first()?.json ?? {};

if (r.confere === true) {
  return [
    {
      json: {
        status: 'ok',
        cliente: { nome: r.nome || 'cliente' },
      },
    },
  ];
}

/*
 * Uma única mensagem para código errado, expirado e tentativas esgotadas. As
 * três diferem para quem está atacando — "expirado" confirma que o código
 * existiu — e não mudam nada para o cliente, que precisa da mesma coisa nos
 * três casos: pedir outro.
 */
return [
  {
    json: {
      status: 'erro',
      mensagem: 'Código inválido ou expirado. Peça um novo código.',
    },
  },
];

/*
 * Evento `solicitacao_login` ("Esqueci minha senha").
 *
 * É a ponte entre os dois provedores: o cadastro está aqui, mas quem guarda a
 * senha é o Supabase. Então geramos uma senha nova, gravamos no Supabase pela
 * chave de serviço e mandamos ao cliente pelo canal que ele escolheu.
 *
 * `acao` decide o caminho no Switch seguinte:
 *   nada       documento não encontrado — respondemos ok assim mesmo
 *   criar      cliente sem usuário no Supabase ainda
 *   atualizar  já tem usuário, só troca a senha
 */
const crypto = require('crypto');

const envelope = $('Validar assinatura').first().json;
const dados = envelope.dados ?? {};
const cliente = $input.first()?.json ?? {};

const encontrado = Boolean(cliente.id_cliente);

// 12 caracteres do gerador criptográfico. base64url não tem "+", "/" nem "=",
// que quebram ao serem copiados de uma mensagem de WhatsApp.
const senha = crypto.randomBytes(9).toString('base64url');

const celular = String(cliente.celular ?? '').replace(/\D/g, '');
const email = String(cliente.email ?? '').trim().toLowerCase();

// O Supabase guarda telefone em E.164. O DDI 55 é acrescentado quando o
// cadastro traz só DDD + número.
const telefoneE164 = celular
  ? '+' + (celular.startsWith('55') && celular.length > 11 ? celular : '55' + celular)
  : null;

return [
  {
    json: {
      acao: !encontrado ? 'nada' : cliente.supabase_user_id ? 'atualizar' : 'criar',
      id_cliente: encontrado ? String(cliente.id_cliente) : null,
      supabase_user_id: cliente.supabase_user_id ?? null,
      nome: cliente.nome ?? 'cliente',
      documento: String(dados.documento ?? ''),
      metodo: String(dados.metodo ?? 'whatsapp'),
      email: email || null,
      celular: celular || null,
      telefone_e164: telefoneE164,
      senha,
    },
  },
];
